94					return
95				}
96				*t = time.Unix(c.Int63n(4102444800), c.Int63n(1e9)).UTC()
97			},
98			func(d *time.Duration, c fuzz.Continue) {
99				if c.Intn(10) < 3 {
100					*d = 0
101					return
102				}
103				*d = time.Duration(c.Int63n(int64(24 * time.Hour)))
104			},
105			func(p *types.ScheduleOverlapPolicy, c fuzz.Continue) {
