package testutils

import (
	"reflect"
	"strings"
	"testing"
	"time"

	fuzz "github.com/google/gofuzz"
	"github.com/stretchr/testify/assert"

	"github.com/uber/cadence/common/types"
)

// FuzzOptions holds the configurable behavior for RunMapperFuzzTest. It is
// mutated by FuzzOption functional options before a fuzz run begins.
type FuzzOptions struct {
	// customFuncs are additional gofuzz generator functions. They are applied
	// after the built-in defaults, so they may override the defaults for the
	// same type.
	customFuncs []interface{}
	// excludedFields are field names that should be zeroed on both the original
	// and the round-tripped value before they are compared. This is used to
	// strip fields that are not expected to survive a round-trip (in addition to
	// the always-stripped protobuf-internal fields).
	excludedFields []string
	// nilChance is the probability (0.0-1.0) that gofuzz leaves a nilable value nil.
	nilChance float64
	// iterations is the number of round-trips to perform.
	iterations int
}

// FuzzOption configures RunMapperFuzzTest behavior.
type FuzzOption func(*FuzzOptions)

// WithCustomFuncs registers additional gofuzz generator functions with the
// underlying fuzzer. They are applied after the built-in default fuzzers, so
// they take precedence for any type they handle. This is how callers register
// domain-specific fuzzers (e.g. enum constraints) that the generic mapper test
// cannot know about.
func WithCustomFuncs(funcs ...interface{}) FuzzOption {
	return func(o *FuzzOptions) {
		o.customFuncs = append(o.customFuncs, funcs...)
	}
}

// WithExcludedFields registers struct field names to be cleared (set to their
// zero value) on both the original and round-tripped values before comparison.
// Fields whose names begin with "XXX_" (and "sizeCache"/"unknownFields") are
// always cleared regardless of this setting.
func WithExcludedFields(fields ...string) FuzzOption {
	return func(o *FuzzOptions) {
		o.excludedFields = append(o.excludedFields, fields...)
	}
}

// WithNilChance sets the probability (0.0-1.0) that the fuzzer leaves a nilable
// value nil.
func WithNilChance(chance float64) FuzzOption {
	return func(o *FuzzOptions) {
		o.nilChance = chance
	}
}

// WithIterations sets the number of round-trips performed by the fuzz test.
func WithIterations(iterations int) FuzzOption {
	return func(o *FuzzOptions) {
		o.iterations = iterations
	}
}

// defaultFuzzOptions returns the baseline configuration used before applying
// any caller-supplied options.
func defaultFuzzOptions() *FuzzOptions {
	return &FuzzOptions{
		nilChance:  0.3,
		iterations: 1000,
	}
}

// defaultFuzzFuncs are the built-in gofuzz generator functions applied to every
// RunMapperFuzzTest run. They constrain values that would otherwise not survive
// a round-trip through the protobuf/thrift representations: times and durations
// (which are truncated / range-limited), plus a handful of commonly-used enums.
//
// These are applied before any WithCustomFuncs, so callers can override them.
func defaultFuzzFuncs() []interface{} {
	return []interface{}{
		// default time fuzzer: bounded, UTC, no monotonic clock so it survives a
		// round-trip through a unix-timestamp representation.
		func(t *time.Time, c fuzz.Continue) {
			if c.Intn(10) < 3 {
				*t = time.Time{}
				return
			}
			*t = time.Unix(c.Int63n(4102444800), c.Int63n(1e9)).UTC()
